  "inlineSchema": "// FitPulse Online Fitness Tracking Platform - Prisma Schema\n// Fully compatible with SQLite (local zero-setup dev) and PostgreSQL (production deployment)\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nmodel User {\n  id            String   @id @default(uuid())\n  name          String\n  email         String   @unique\n  password_hash String\n  role          String   @default(\"USER\") // \"USER\" | \"ADMIN\"\n  profile_image String?\n  is_active     Boolean  @default(true)\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  workouts       WorkoutLog[]\n  contents       FitnessContent[]\n  userChallenges UserChallenge[]\n  auditLogs      AuditLog[]\n\n  @@map(\"users\")\n}\n\nmodel WorkoutLog {\n  id               String   @id @default(uuid())\n  user_id          String\n  type             String // Cardio, Strength, HIIT, Yoga, Cycling, Running, etc.\n  duration_minutes Int\n  intensity        String   @default(\"MEDIUM\") // \"LOW\" | \"MEDIUM\" | \"HIGH\"\n  calories_burned  Int\n  date             DateTime @default(now())\n  notes            String?\n  created_at       DateTime @default(now())\n  updated_at       DateTime @updatedAt\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@index([user_id])\n  @@index([date])\n  @@map(\"workout_logs\")\n}\n\nmodel FitnessContent {\n  id          String   @id @default(uuid())\n  creator_id  String\n  title       String\n  description String\n  category    String // Guide, Workout Routine, Nutrition, Recovery\n  media_url   String?\n  status      String   @default(\"PENDING\") // \"PENDING\" | \"APPROVED\" | \"REJECTED\"\n  feedback    String?\n  created_at  DateTime @default(now())\n  updated_at  DateTime @updatedAt\n\n  creator User @relation(fields: [creator_id], references: [id], onDelete: Cascade)\n\n  @@index([status])\n  @@index([creator_id])\n  @@map(\"fitness_contents\")\n}\n\nmodel Challenge {\n  id            String   @id @default(uuid())\n  title         String\n  description   String\n  target_metric String // \"CALORIES\" | \"DURATION\" | \"WORKOUT_COUNT\"\n  target_value  Int\n  start_date    DateTime\n  end_date      DateTime\n  reward_badge  String // e.g. \"Flame Master\", \"Endurance Titan\", \"Iron Will\"\n  created_at    DateTime @default(now())\n\n  participants UserChallenge[]\n\n  @@map(\"challenges\")\n}\n\nmodel UserChallenge {\n  id               String    @id @default(uuid())\n  user_id          String\n  challenge_id     String\n  status           String    @default(\"IN_PROGRESS\") // \"IN_PROGRESS\" | \"COMPLETED\" | \"ABANDONED\"\n  current_progress Int       @default(0)\n  joined_at        DateTime  @default(now())\n  completed_at     DateTime?\n\n  user      User      @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  challenge Challenge @relation(fields: [challenge_id], references: [id], onDelete: Cascade)\n\n  @@unique([user_id, challenge_id])\n  @@index([user_id])\n  @@index([challenge_id])\n  @@map(\"user_challenges\")\n}\n\nmodel SystemSetting {\n  id          String   @id @default(uuid())\n  key         String   @unique\n  value       String\n  description String?\n  updated_by  String?\n  updated_at  DateTime @updatedAt\n\n  @@map(\"system_settings\")\n}\n\nmodel AuditLog {\n  id        String   @id @default(uuid())\n  user_id   String?\n  action    String // e.g. \"USER_REGISTER\", \"USER_LOGIN\", \"LOG_WORKOUT\", \"UPDATE_CONTENT_STATUS\", \"UPDATE_SYSTEM_SETTING\"\n  details   String? // JSON formatted or readable description\n  timestamp DateTime @default(now())\n\n  user User? @relation(fields: [user_id], references: [id], onDelete: SetNull)\n\n  @@index([timestamp])\n  @@index([user_id])\n  @@map(\"audit_logs\")\n}\n",
